using System;
using System.Runtime.CompilerServices;

class Program
{
    public static void Main()
    {
        Log(default(int));
    }
    const string p = nameof(p);
    static void Log(int p, [CallerArgumentExpression(p)] string arg)
    {
        Console.WriteLine(arg);
    }
}

